    except (OSError, ValueError):
        return default


def _write(p: Path, data) -> None:
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_name(p.name + ".tmp")
    tmp.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
    tmp.replace(p)


def _proj(slug: str) -> Path:
    p = PROJECTS / slug
    if not p.exists():
        raise SystemExit(f"project '{slug}' not found in {PROJECTS}")
    return p


def shots_path(slug: str) -> Path:
    return PROJECTS / slug / "broll" / "shots.json"


def load_shots(slug: str) -> dict | None:
    return _read(shots_path(slug))


# =============================================================================================== time parsing
_OBS_RX = re.compile(r"(\d{4})-(\d{2})-(\d{2})[ T_](\d{2})[-_:.](\d{2})[-_:.](\d{2})")


def parse_obs_name(name: str) -> datetime | None:
    """'2026-10-06 13-51-50.mp4' (OBS default), '2026-10-10T14_25_31.zip' (Flashback) -> naive local datetime."""
    m = _OBS_RX.search(Path(name).name)
    if not m:
        return None
    try:
        return datetime(*[int(x) for x in m.groups()])
    except ValueError:
        return None


def _probe_duration(path: Path) -> float | None:
    try:
        r = subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", str(path)],
                           capture_output=True, text=True, timeout=60)
        return float(r.stdout.strip())
    except (OSError, ValueError, subprocess.TimeoutExpired):
        return None


def video_window(slug: str) -> dict:
    """Wall-clock window of the project's recording: {start, end, dur, file, how} (epoch seconds, local clock)."""
    pj = _read(PROJECTS / slug / "project.json", {}) or {}
    game = ((pj.get("sources") or {}).get("game") or {}).get("file")
    f = Path(game) if game else None
    dur = float(pj.get("duration_s") or 0) or (_probe_duration(f) if f and f.exists() else 0) or 0.0
    dt = parse_obs_name(f.name) if f else None
    if dt is not None:
        start, how = dt.timestamp(), "OBS filename"
    elif f is not None and f.exists():
        start, how = f.stat().st_mtime - dur, "file mtime minus duration"
    else:
        raise SystemExit(f"{slug}: cannot place the recording in time (no game file / timestamp)")
    return {"start": start, "end": start + dur, "dur": dur, "file": str(f) if f else None, "how": how}


def replay_window(path: Path) -> dict:
    """Wall-clock window of a replay file: {start, end, dur, kind}. Verified against real files:
    Flashback metadata.json `name` is the SAVE time (start = name - total_ticks/20); Replay Mod metaData.json `date`
    is the START (epoch ms) and `duration` is in ms."""
    path = Path(path)
    with zipfile.ZipFile(path) as z:
        names = set(z.namelist())
        if "metadata.json" in names:                                             # Flashback
            m = json.loads(z.read("metadata.json"))
            end_dt = parse_obs_name(str(m.get("name") or "")) or parse_obs_name(path.name)
            if end_dt is None:
                raise ValueError(f"{path.name}: no timestamp in metadata name")
            dur = float(m.get("total_ticks", 0)) / 20.0
            end = end_dt.timestamp()
            return {"start": end - dur, "end": end, "dur": dur, "kind": "flashback", "path": str(path)}
        if "metaData.json" in names:                                              # Replay Mod
            m = json.loads(z.read("metaData.json"))
            start = float(m["date"]) / 1000.0
            dur = float(m.get("duration", 0)) / 1000.0
            return {"start": start, "end": start + dur, "dur": dur, "kind": "replaymod", "path": str(path)}
    raise ValueError(f"{path}: not a Flashback or Replay Mod archive")


def list_replays(dirs: list[Path] | None = None) -> list[dict]:
    out = []
    for d in dirs or [FLASHBACK_DIR, REPLAYMOD_DIR]:
        if not Path(d).is_dir():
            continue
        for f in sorted(Path(d).iterdir()):
            if f.suffix.lower() in (".zip", ".mcpr"):
                try:
                    out.append(replay_window(f))
                except (OSError, ValueError, KeyError, zipfile.BadZipFile):
                    continue
    return out


def overlap_s(a: dict, b: dict) -> float:
    return max(0.0, min(a["end"], b["end"]) - max(a["start"], b["start"]))


def find_replay(slug: str, dirs: list[Path] | None = None, min_overlap_s: float = 10.0,
                window: dict | None = None) -> dict | None:
    """The replay overlapping the project's recording in wall-clock time (largest overlap; Flashback preferred because
    its reader exists). -> replay_window dict + {'overlap_s'} or None."""
    vw = window or video_window(slug)
    cands = []
    for r in list_replays(dirs):
        ov = overlap_s(vw, r)
        if ov >= min_overlap_s:
            cands.append({**r, "overlap_s": round(ov, 2)})
    if not cands:
        return None
    cands.sort(key=lambda r: (r["kind"] == "flashback", r["overlap_s"], r["end"]), reverse=True)
    return cands[0]


# =============================================================================================== sync
def estimate_sync(vw: dict, rw: dict) -> dict:
    """Timestamp sync: offset_s = replay time (s) at video t=0. Negative = the replay started after the recording did."""
    off = vw["start"] - rw["start"]
    ov = overlap_s(vw, rw)
    cover = ov / max(vw["dur"], 1e-6)
    # clocks agree to ~1-3 s when OBS and the game ran on one PC; a low overlap means shots near the ends fall outside
    conf = round(0.35 * min(1.0, cover) + 0.05, 3)
    return {"offset_s": round(off, 3), "method": "timestamps", "confidence": conf,
            "notes": f"video start {datetime.fromtimestamp(vw['start']):%H:%M:%S} ({vw['how']}) vs replay start "
                     f"{datetime.fromtimestamp(rw['start']):%H:%M:%S}; overlap {ov:.0f}s of {vw['dur']:.0f}s video; "
                     "timestamps are only good to a few seconds - refine with motion-xcorr"}


def _smooth(x: np.ndarray, n: int) -> np.ndarray:
    if n <= 1 or len(x) < 2:
        return x
    k = np.ones(n) / n
    return np.convolve(np.pad(x, (n // 2, n - 1 - n // 2), mode="edge"), k, mode="valid")


def _z(x: np.ndarray) -> np.ndarray:
    s = x.std()
    return (x - x.mean()) / s if s > 1e-9 else x * 0.0


def replay_activity(track, fps: float = 4.0) -> np.ndarray:
    """Camera-activity series of the recording player at `fps`, index j = replay second j/fps (from tick 0).
    activity = z(speed) + z(yaw rate) + 0.5*z(pitch rate): what a screen recording's motion energy follows."""
    x, z, yaw, pitch = (np.asarray(a, dtype=float) for a in (track.x, track.z, track.yaw, track.pitch))
    start = int(getattr(track, "start", 0))
    n = len(x)
    sp = np.hypot(np.diff(x, prepend=x[0]), np.diff(z, prepend=z[0])) * 20.0
    dyaw = np.abs((np.diff(yaw, prepend=yaw[0]) + 180.0) % 360.0 - 180.0) * 20.0
    dpitch = np.abs(np.diff(pitch, prepend=pitch[0])) * 20.0
    sm = max(1, int(round(20 / fps)))
    a = _z(_smooth(sp, sm)) + _z(_smooth(np.minimum(dyaw, 720), sm)) + 0.5 * _z(_smooth(dpitch, sm))
    total_s = (start + n) / 20.0
    out = np.zeros(int(math.ceil(total_s * fps)) + 1)
    idx = np.clip((np.arange(len(out)) / fps * 20 - start).astype(int), 0, n - 1)
    out[:] = a[idx]
    return out


def video_motion_series(path: str | Path, fps: float = 4.0, start: float = 0.0, dur: float | None = None) -> np.ndarray:
    """Motion energy of a video at `fps` (cheap: ffmpeg downscales to 64x36 gray). Index k = video second start+k/fps."""
    w, h = 64, 36
    cmd = ["ffmpeg", "-v", "error", "-threads", "2", "-ss", f"{start:.3f}", "-i", str(path)]
    if dur:
        cmd += ["-t", f"{dur:.3f}"]
    cmd += ["-an", "-vf", f"fps={fps},scale={w}:{h}:flags=area,format=gray", "-f", "rawvideo", "-"]
    r = subprocess.run(cmd, capture_output=True, timeout=1800)
    buf = np.frombuffer(r.stdout, dtype=np.uint8)
    n = len(buf) // (w * h)
    if n < 3:
        return np.zeros(0)
    fr = buf[: n * w * h].reshape(n, h, w).astype(np.float32)
    m = np.abs(np.diff(fr, axis=0)).mean(axis=(1, 2))
    return np.concatenate([[m[0]], m])                      # index k <-> frame k


def xcorr_offset(v: np.ndarray, r: np.ndarray, fps: float, prior_s: float = 0.0, max_lag_s: float = 15.0,
                 min_overlap_s: float = 10.0, smooth_s: float = 1.0) -> dict:
    """Find offset o (replay time at video t0) maximising Pearson correlation of v[k] with r[k + o*fps].
    Search prior +- max_lag. confidence in 0..1 combines the peak height and its prominence over the best
    rival peak further than 1.5 s away. Returns {offset_s, confidence, peak, second, n}."""
    sm = max(1, int(round(smooth_s * fps)))
    v = _z(_smooth(np.asarray(v, float), sm))
    r = _z(_smooth(np.asarray(r, float), sm))
    lo, hi = int(round((prior_s - max_lag_s) * fps)), int(round((prior_s + max_lag_s) * fps))
    min_n = int(min_overlap_s * fps)
    shifts, cors = [], []
    for s in range(lo, hi + 1):
        k0, k1 = max(0, -s), min(len(v), len(r) - s)
        if k1 - k0 < min_n:
            continue
        a, b = v[k0:k1], r[k0 + s:k1 + s]
        sa, sb = a.std(), b.std()
        if sa < 1e-9 or sb < 1e-9:
            continue
        shifts.append(s)
        cors.append(float(np.mean((a - a.mean()) * (b - b.mean())) / (sa * sb)))
    if not shifts:
        return {"offset_s": prior_s, "confidence": 0.0, "peak": 0.0, "second": 0.0, "n": 0}
    cors_a = np.array(cors)
    i = int(np.argmax(cors_a))
    peak = cors_a[i]
    far = np.abs(np.array(shifts) - shifts[i]) > 1.5 * fps
    second = float(cors_a[far].max()) if far.any() else 0.0
    frac = 0.0                                              # parabolic sub-sample refinement
    if 0 < i < len(cors_a) - 1:
        a, b, c = cors_a[i - 1], cors_a[i], cors_a[i + 1]
        den = a - 2 * b + c
        frac = 0.5 * (a - c) / den if abs(den) > 1e-9 else 0.0
        frac = max(-1.0, min(1.0, frac))
    conf = max(0.0, min(1.0, (peak - 0.2) / 0.5)) * max(0.0, min(1.0, (peak - second) / 0.2))
    return {"offset_s": (shifts[i] + frac) / fps, "confidence": round(float(conf), 3), "peak": round(float(peak), 3),
            "second": round(second, 3), "n": len(shifts)}


def refine_sync(video_path: str | Path | None, replay, est: dict, min_conf: float = 0.4, fps: float = 4.0,
                max_lag_s: float = 15.0, v_series: np.ndarray | None = None) -> dict:
    """Refine a timestamp estimate by cross-correlating video motion energy with the replay's player speed / yaw-rate.
    Falls back to the timestamp estimate (with a note) when the correlation is weak or inputs are missing."""
    try:
        r_series = replay_activity(replay.player_track(), fps)
        v = v_series if v_series is not None else video_motion_series(video_path, fps)
    except Exception as e:                                   # noqa: BLE001 - never block planning on sync refinement
        return {**est, "notes": est["notes"] + f"; xcorr skipped ({type(e).__name__}: {e})"}
    if len(v) < 10 * fps:
        return {**est, "notes": est["notes"] + "; xcorr skipped (video too short)"}
    res = xcorr_offset(v, r_series, fps, est["offset_s"], max_lag_s)
    if res["confidence"] >= min_conf:
        return {"offset_s": round(res["offset_s"], 3), "method": "motion-xcorr", "confidence": res["confidence"],
                "notes": f"xcorr peak r={res['peak']} (rival {res['second']}); timestamp guess was "
                         f"{est['offset_s']:+.2f}s, refined shift {res['offset_s'] - est['offset_s']:+.2f}s"}
    return {**est, "notes": est["notes"] + f"; xcorr too weak (conf {res['confidence']}, r={res['peak']}) - "
                                           "kept the timestamp offset"}


# =============================================================================================== replay access
@dataclass
class SynthTrack:
    start: int
    x: np.ndarray
    y: np.ndarray
    z: np.ndarray
    yaw: np.ndarray
    pitch: np.ndarray
    eye_height: float = 1.62

    def _i(self, t: int) -> int:
        return min(max(int(t) - self.start, 0), len(self.x) - 1)

    def pos(self, t):
        i = self._i(t)
        return float(self.x[i]), float(self.y[i]), float(self.z[i])

    def rot(self, t):
        i = self._i(t)
        return float(self.yaw[i]), float(self.pitch[i])

    def speed(self, t, window=10):
        a, b = self._i(t - window // 2), self._i(t + window // 2)
        return 0.0 if a == b else float(math.hypot(self.x[b] - self.x[a], self.z[b] - self.z[a])) / ((b - a) / 20.0)


@dataclass
class SynthEvent:
    tick: int
    kind: str
    data: dict = field(default_factory=dict)


class SynthReplay:
    """Duck-typed stand-in for flashback_replay.Replay (synthetic player track + events) for tests and dry runs."""
    synthetic = True

    def __init__(self, track: SynthTrack, events=(), name="synthetic"):
        self.path = Path(f"{name}.zip")
        self.track = track
        self.total_ticks = track.start + len(track.x)
        self.events = sorted(events, key=lambda e: e.tick)
        self.dimension_log: list[tuple[int, str]] = [(0, "minecraft:overworld")]
        self.markers: list = []

    @property
    def duration_s(self):
        return self.total_ticks / 20.0

    def player_track(self, who=None):
        return self.track

    def events_of(self, *kinds):
        return [e for e in self.events if e.kind in kinds]


def synthetic_replay(total_s: float, seed: int = 7, events=()) -> SynthReplay:
    """Player walks / pauses / looks around in random bursts; deterministic per seed."""
    rng = np.random.default_rng(seed)
    n = int(total_s * 20)
    x, z = np.zeros(n), np.zeros(n)
    y = np.full(n, 64.0)
    yaw, pitch = np.zeros(n), np.zeros(n)
    px = pz = 0.0
    heading, pt = 0.0, 0.0
    i = 0
    while i < n:
        L = int(rng.uniform(1.5, 6.0) * 20)
        walking = rng.random() < 0.6
        turn = rng.normal(0, 40) if rng.random() < 0.6 else 0.0
        spd = rng.uniform(3.5, 5.6) if walking else 0.0
        dpt = rng.normal(0, 14)
        for j in range(i, min(n, i + L)):
            heading += turn / 20.0 / max(L / 20.0, 1.0)
            pt = float(np.clip(pt + dpt / L, -60, 60))
            px += -math.sin(math.radians(heading)) * spd / 20
            pz += math.cos(math.radians(heading)) * spd / 20
            x[j], z[j], yaw[j], pitch[j] = px, pz, heading, pt
        i += L
    return SynthReplay(SynthTrack(0, x, y, z, yaw, pitch), events)


def load_replay(path: str | Path):
    """flashback_replay.load(path) (Flashback only; Replay Mod .mcpr has no reader yet)."""
    if str(path).lower().endswith(".mcpr"):
        raise NotImplementedError("Replay Mod (.mcpr) shots need a reader; only Flashback replays are supported so far")
    from . import flashback_replay as F
    return F.load(path)


# =============================================================================================== director
def _words(tr: dict) -> list[dict]:
    return [w for s in (tr or {}).get("segments", []) for w in s.get("words", [])]


class _Ctx:
    """Everything the director knows about the episode (source-time world)."""

    def __init__(self, slug: str, C: dict):
        self.slug, self.C = slug, C
        self.proj = _proj(slug)
        self.pj = _read(self.proj / "project.json", {}) or {}
        self.tr = _read(self.proj / "work" / "transcript.json", {"segments": []}) or {"segments": []}
        self.sig = _read(self.proj / "work" / "signals.json", {}) or {}
        self.edl = _read(self.proj / "edit.json")
        self.words = _words(self.tr)
        self.total = float(self.sig.get("duration_s") or self.pj.get("duration_s") or
                           (self.words[-1]["end"] if self.words else 0.0))
        self.beats = self._beats()
        self.spans = self._spans()
        self.blocked = self._blocked()
        self.dark = [tuple(d) for d in self.sig.get("dark", [])]

    # -- beats from the autoplanner (lexicon + voice peaks + death screens)
    def _beats(self) -> list[dict]:
        try:
            from .autoplan import Planner
            return Planner(self.slug).beats()
        except Exception as e:                                   # noqa: BLE001
            print(f"[cinematic] autoplan beats unavailable ({type(e).__name__}: {e}); using death screens only",
                  file=sys.stderr)
            return [{"t": d["t"], "end": d["t"] + 0.5, "moment": "death", "score": 5, "death_screen": True,
                     "phrase": "<death screen>", "keyword": ""} for d in self.sig.get("death_screens", [])]

    def _spans(self):
        if not self.edl:
            return None
        from . import assets as A
        from .edl import build_spans

        def look(i):
            try:
                return A.get(i)
            except Exception:                                      # noqa: BLE001
                return None
        try:
            return build_spans(self.edl, look)
        except Exception:                                          # noqa: BLE001
            return None

    def main_spans(self):
        """Spans we may put a shot in: speed-1 source footage that is not the cold-open teaser."""
        if self.spans is None:
            return [(0.0, self.total, None, 0.0)]
        return [(sp.src_in, sp.src_in + (sp.out_end - sp.out_start) * sp.speed, sp.seg_id, sp.out_start)
                for sp in self.spans if sp.src_in is not None and sp.speed == 1.0
                and not str(sp.seg_id or "").startswith("cold")]

    def out_time(self, t: float) -> float | None:
        if self.spans is None:
            return t
        from .edl import src_to_out
        main = [sp for sp in self.spans if not str(sp.seg_id or "").startswith("cold")]
        return src_to_out(main, t)

    def _blocked(self) -> list[tuple[float, float, str]]:
        b: list[tuple[float, float, str]] = []
        for x in self.beats:
            if x.get("death_screen"):
                continue
            if x["score"] >= 3:
                b.append((x["t"] - 0.2, x["end"] + 0.25, f"{x['moment']}:{x.get('keyword') or x.get('phrase')}"))
        for d in self.sig.get("death_screens", []):
            b.append((d["t"] - 0.05, d.get("end", d["t"] + 3.0) + 0.3, "death screen"))
        try:
            from .autoplan import running_gags
            for word, occ in running_gags(self.words).items():
                for t, _ in occ:
                    b.append((t - 0.35, t + 0.9, f"running-gag counter '{word}'"))
        except Exception:                                          # noqa: BLE001
            pass
        # existing meme cutaways / green screens / stickers (source-time view)
        if self.edl and self.spans is not None:
            for a, z, why in busy_output_intervals(self.edl, self.spans):
                for sp in self.spans:
                    if sp.src_in is None or str(sp.seg_id or "").startswith("cold"):
                        continue
                    lo, hi = max(a, sp.out_start), min(z, sp.out_end)
                    if hi > lo:
                        b.append((sp.src_in + (lo - sp.out_start) * sp.speed - 0.2,
                                  sp.src_in + (hi - sp.out_start) * sp.speed + 0.2, why))
        return b

    def hits(self, a: float, z: float) -> str | None:
        for x, y, why in self.blocked:
            if a < y and z > x:
                return why
        return None

    def window_ok(self, a: float, z: float, hook_s: float) -> bool:
        if a < 0 or z > self.total + 1e-6 or self.hits(a, z):
            return False
        inside = [s for s in self.main_spans() if s[0] - 1e-6 <= a and z <= s[1] + 1e-6]
        if not inside:
            return False
        o = self.out_time(a)
        return o is not None and o >= hook_s

    def calm(self, a: float, z: float) -> bool:
        return not any(b["score"] >= 2 and a - 0.5 < b["end"] and z + 1.0 > b["t"] for b in self.beats)

    def dark_frac(self, a: float, z: float) -> float:
        ov = sum(max(0.0, min(z, e) - max(a, s)) for s, e in self.dark)
        return ov / max(z - a, 1e-6)


def busy_output_intervals(edl: dict, spans, pad: float = 0.0) -> list[tuple[float, float, str]]:
    """Output-time intervals a cinematic shot must not sit on: meme cutaways / cards, green screens, video clips,
    image stickers, sticker_pop motion graphics (other cinematic overlays are ignored)."""
    from .edl import resolve_time
    out = []
    for sp in spans:
        if sp.src_in is None:
            out.append((sp.out_start - pad, sp.out_end + pad, f"{edl['segments'][sp.seg_index].get('type')} segment"))
    for ev in edl.get("overlays", []):
        if ev.get("cinematic"):
            continue
        typ = ev.get("type")
        if typ not in ("greenscreen", "video", "image") and ev.get("template") != "sticker_pop":
            continue
        at = resolve_time(ev, spans, [], "busy")
        if at is None:
            continue
        d = ev.get("dur") or 1.5
        out.append((at - pad, at + d + pad, f"existing {typ if typ != 'motion' else 'sticker'} overlay"))
    return out


def _clamp_dur(kind: str, base: float) -> float:
    return round(min(MAX_DUR, max(MIN_DUR, base * DUR_MULT.get(kind, 1.0))), 2)


def _place(ctx: _Ctx, anchor: float, dur: float, direction: str, C: dict, max_shift: float = 4.0,
           step: float = 0.25):
    """Find (start, dur) near `anchor`. direction 'after': start >= anchor, scanning later; 'before': the shot must END
    at or before anchor, scanning earlier; 'around': try anchor then alternate outwards. Shrinks to MIN_DUR on conflict."""
    for d in sorted({dur, max(MIN_DUR, dur - 0.5), MIN_DUR}, reverse=True):
        k = 0
        while k * step <= max_shift:
            if direction == "after":
                cands = [anchor + k * step]
            elif direction == "before":
                cands = [anchor - d - k * step]
            else:
                cands = [anchor + k * step, anchor - k * step] if k else [anchor]
            for s in cands:
                if ctx.window_ok(s, s + d, C["hook_s"]):
                    return round(s, 2), round(d, 2)
            k += 1
    return None


def _replay_events_video(replay, offset_s: float, ctx: _Ctx) -> list[dict]:
    out = []
    if replay is None:
        return out
    for e in getattr(replay, "events", []):
        if e.kind not in ("death", "dimension", "explosion", "damage", "kill", "teleport"):
            continue
        vt = e.tick / 20.0 - offset_s
        if 0 <= vt < ctx.total:
            out.append({"kind": e.kind, "video_t": vt, "tick": e.tick, "data": getattr(e, "data", {})})
    return out


def _night_session(ctx: _Ctx) -> bool:
    dark = sum(e - s for s, e in ctx.dark)
    return ctx.total > 0 and dark / ctx.total > 0.6


def _candidates(ctx: _Ctx, C: dict, replay, sync: dict) -> list[dict]:
    cands: list[dict] = []
    base = C["shot_len_s"]
    allowed = set(C["allowed_kinds"])
    trust = replay is not None and sync.get("confidence", 0) >= C["trust_replay_events"]
    revents = _replay_events_video(replay, sync["offset_s"], ctx) if trust else []

    def add(kind, anchor, direction, reason, prio_bonus=0.0, moment=None, why_src="transcript", **kw):
        cands.append({"kind": kind, "anchor": anchor, "dir": direction, "reason": reason, "moment": moment or
                      KIND_MOMENT[kind], "prio": KIND_PRIO[kind] + prio_bonus, "src": why_src, **kw})

    # intro: first calm window after the hook
    first = ctx.main_spans()[0][0] if ctx.main_spans() else 0.0
    t = max(first, 0.0)
    dur0 = _clamp_dur("aerial_establish", base)
    best = None
    while t + dur0 <= ctx.total:
        if ctx.window_ok(t, t + dur0, C["hook_s"]):
            best = best if best is not None else t
            if ctx.calm(t, t + dur0):
                best = t
                break
        t += 0.5
    if best is not None:
        add("aerial_establish", best, "around", "establishing shot: first calm moment after the hook", moment="intro")

    deaths = [b for b in ctx.beats if b.get("death_screen")]
    for b in deaths:
        add("death_reveal", b["t"] - 0.1, "before", "pull-back from above, ends just before the death screen",
            moment="death", death_t=b["t"])
    shown_death = [b["t"] for b in deaths]
    flip = {"orbit": False, "pov": False}
    for b in ctx.beats:
        m, sc = b["moment"], b["score"]
        if b.get("death_screen"):
            continue
        after = b["end"] + 0.3
        if m in ("loot", "victory") and sc >= 3:
            flip["orbit"] = not flip["orbit"]
            add("push_in" if flip["orbit"] else "orbit", after, "after",
                f"{m} beat '{b.get('keyword') or b.get('phrase')}' - hero shot after the line lands", prio_bonus=sc / 2,
                moment=m if m in MOMENTS else "loot")
        elif m in ("panic", "jumpscare", "explosion") and sc >= 3:
            flip["pov"] = not flip["pov"]
            add("pov" if flip["pov"] else "track_follow", after, "after",
                f"{m} beat '{b.get('keyword') or b.get('phrase')}' - short chase cam", prio_bonus=sc / 2,
                moment="panic")
        elif m == "location":
            add("nether_arrival", after, "after", f"new place: '{b.get('phrase')}'", prio_bonus=2, moment="new_place")
        elif m == "outro":
            add("outro_pullup", after, "after", "outro line landed - pull up and out", moment="outro")
    for ev in revents:
        k, vt = ev["kind"], ev["video_t"]
        if k == "death" and not any(abs(vt - d) < 8 for d in shown_death):
            add("death_reveal", vt - 0.1, "before", "replay: player died", why_src="replay", death_t=vt, prio_bonus=-5)
        elif k == "dimension":
            add("nether_arrival", vt + 0.8, "after", f"replay: dimension change {ev['data'].get('dimension', '')}",
                why_src="replay", prio_bonus=3, moment="new_place")
        elif k == "explosion":
            add("push_in", vt + 0.8, "after", "replay: explosion nearby", why_src="replay", moment="panic",
                prio_bonus=-6)
        elif k == "kill":
            add("track_follow", vt + 0.4, "after", f"replay: kill ({ev['data'].get('type', '?')})", why_src="replay",
                moment="panic", prio_bonus=-8)

    # long calm stretches -> flyby / timelapse (better when the recorded footage is dark/dull there)
    pts = sorted([b["t"] for b in ctx.beats if b["score"] >= 3] + [b["end"] for b in ctx.beats if b["score"] >= 3])
    lo = max(first, 0.0)
    edges = [lo] + [p for p in pts if p > lo] + [ctx.total]
    n_calm = 0
    for a, z in zip(edges, edges[1:]):
        if z - a >= C["calm_min_s"]:
            span = z - a
            d = _clamp_dur("flyby", base)
            best_s, best_dark = a + span / 2 - d / 2, -1.0
            s = a + 1.5
            while s + d <= z - 1.5:
                df = ctx.dark_frac(s, s + d)
                if df > best_dark + 0.05:
                    best_s, best_dark = s, df
                s += 1.0
            kind = "timelapse" if (n_calm % 2 == 1) else "flyby"
            if trust:
                try:
                    sp = replay.player_track().speed(int((best_s + sync["offset_s"]) * 20), 200)
                    kind = "flyby" if sp > 2.5 else "timelapse"
                except Exception:                                   # noqa: BLE001
                    pass
            n_calm += 1
            add(kind, best_s, "around", f"calm {span:.0f}s stretch" + (" (dark footage)" if best_dark > 0.3 else ""),
                prio_bonus=min(span, 40) / 10 + (4 if best_dark > 0.3 else 0),
                moment="travel" if kind == "flyby" else "build", max_shift=3.0)
    out = []                                                        # filter / remap by allowed kinds
    for c in cands:
        if c["kind"] in allowed:
            out.append(c)
            continue
        alt = next((k for k in FAMILY.get(c["kind"], []) if k in allowed), None)
        if alt:
            c["kind"] = alt
            out.append(c)
    return out


def plan_shots(slug: str, replay=None, settings: dict | None = None, sync: dict | None = None,
               write: bool = True) -> dict:
    """Choose cinematic shots for an episode. `replay` = Replay-like object, path, or None (auto-find a Flashback replay;
    no replay -> abstract shots without ticks). Returns the shots.json dict (written unless write=False)."""
    S = settings if settings is not None else SET.load(slug)
    C = cfg(S)
    ctx = _Ctx(slug, C)
    rpath, rkind, rw = None, "flashback", None
    notes: list[str] = []
    if isinstance(replay, (str, Path)):
        rw = replay_window(Path(replay))
        rpath, rkind = str(replay), rw["kind"]
        replay = load_replay(replay)
    elif replay is None:
        found = find_replay(slug)
        if found:
            rw, rpath, rkind = found, found["path"], found["kind"]
            try:
                replay = load_replay(found["path"])
            except NotImplementedError as e:
                notes.append(str(e))
                replay = None
        else:
            notes.append("no replay overlaps this recording in time - shots are planned without replay ticks")
    else:
        rpath = str(getattr(replay, "path", ""))
        rkind = "synthetic" if getattr(replay, "synthetic", False) else "flashback"
    if sync is None:
        if rw is not None:
            vw = video_window(slug)
            sync = estimate_sync(vw, rw)
            if C["refine_sync"] and replay is not None and vw.get("file") and Path(vw["file"]).exists():
                sync = refine_sync(vw["file"], replay, sync, C["sync_min_confidence"])
        else:
            sync = {"offset_s": 0.0, "method": "timestamps", "confidence": 0.0, "notes": "no replay: offset unknown"}
    sync = {**sync, "offset_s": float(sync["offset_s"])}
    cands = _candidates(ctx, C, replay, sync) if C["enabled"] else []

    # ---- choose: greedy by priority under gap / rate caps
    n_max = max(1 if ctx.total > 40 else 0, int(C["max_shots_per_min"] * ctx.total / 60.0 + 0.5))
    per_min = max(1, math.ceil(C["max_shots_per_min"]))
    chosen: list[dict] = []
    skipped: list[dict] = []
    track = replay.player_track() if replay is not None and hasattr(replay, "player_track") else None
    ticks_total = getattr(replay, "total_ticks", None)
    dull = ("aerial_establish", "flyby", "timelapse")
    for c in sorted(cands, key=lambda c: -(c["prio"] + (ctx.dark_frac(c["anchor"], c["anchor"] + 3) * 3
                                                        if c["kind"] in dull else 0))):
        if len(chosen) >= n_max:
            skipped.append({"kind": c["kind"], "reason": c["reason"], "why": "shot budget used up"})
            continue
        dur = _clamp_dur(c["kind"], C["shot_len_s"])
        placed = _place(ctx, c["anchor"], dur, c["dir"], C, max_shift=c.get("max_shift", 4.0))
        if placed is None:
            skipped.append({"kind": c["kind"], "reason": c["reason"], "why": "no free window (covers a punchline / "
                            "counter / death screen / meme / cut)"})
            continue
        s, d = placed
        if any(not (s >= o["video_t"] + o["dur_s"] + C["min_gap_s"] or s + d + C["min_gap_s"] <= o["video_t"])
               for o in chosen):
            skipped.append({"kind": c["kind"], "reason": c["reason"],
                            "why": f"closer than {C['min_gap_s']:g}s to another shot"})
            continue
        times = sorted([o["video_t"] for o in chosen] + [s])
        if any(sum(1 for q in times if 0 <= q - t0 < 60) > per_min for t0 in times):
            skipped.append({"kind": c["kind"], "reason": c["reason"], "why": "per-minute cap"})
            continue
        tick = round((s + sync["offset_s"]) * 20) if replay is not None else None
        ticks = round(d * 20)
        if tick is not None and ticks_total is not None and (tick < 0 or tick + ticks > ticks_total):
            skipped.append({"kind": c["kind"], "reason": c["reason"],
                            "why": f"outside the replay (tick {tick} of {ticks_total})"})
            continue
        chosen.append({"kind": c["kind"], "moment": c["moment"], "reason": c["reason"], "video_t": s, "dur_s": d,
                       "replay_tick": tick, "ticks": ticks, "src": c["src"], "death_t": c.get("death_t")})
    chosen.sort(key=lambda o: o["video_t"])
    for i in range(1, len(chosen)):                          # variety: never the same kind back to back
        if chosen[i]["kind"] == chosen[i - 1]["kind"]:
            alt = next((k for k in FAMILY.get(chosen[i]["kind"], []) if k in C["allowed_kinds"]
                        and k != chosen[i - 1]["kind"]), None)
            if alt:
                chosen[i]["kind"] = alt
    night = _night_session(ctx)
    shots = [_make_shot(C, track, o, n, night) for n, o in enumerate(chosen, 1)]
    plan = {"project": slug, "replay": rpath, "replay_kind": rkind, "sync": sync,
            "settings": {k: C[k] for k in DEFAULTS if k in C} | {"allowed_kinds": C["allowed_kinds"]},
            "notes": notes, "skipped": skipped, "shots": shots}
    if write:
        _write(shots_path(slug), plan)
    return plan


def _make_shot(C: dict, track, o: dict, n: int, night: bool) -> dict:
    kind = o["kind"]
    params = {"camera": copy.deepcopy(CAMERA[kind])}
    anchor = None
    if track is not None and o["replay_tick"] is not None:
        tk = o["replay_tick"] + (o["ticks"] if kind == "death_reveal" else 0)     # the reveal ends where the player fell
        x, y, z = track.pos(tk)
        yaw, pitch = track.rot(tk)
        anchor = {"tick": int(tk), "x": round(x, 2), "y": round(y, 2), "z": round(z, 2),
                  "yaw": round(yaw, 1), "pitch": round(pitch, 1)}
    params["anchor"] = anchor
    vis = {"hide_gui": True, "hide_nametags": True, "hide_chat": True, "night_vision": False, "time_of_day": None}
    tod = C["time_of_day"]
    if tod == "golden" or (tod == "auto" and night and kind == "outro_pullup"):
        vis["time_of_day"] = 12000                  # golden hour
    elif tod == "day":
        vis["time_of_day"] = 6000
    if night and tod == "auto" and kind in ("nether_arrival", "track_follow", "pov", "orbit", "push_in", "death_reveal"):
        vis["night_vision"] = True
    params["visuals"] = vis
    params["fps"] = int(C["pov_fps"] if kind == "pov" else C["fps"])
    if kind == "timelapse":
        params["replay_ticks_covered"] = int(o["ticks"] * params["camera"]["time_scale"])
    if o.get("death_t") is not None:
        params["death_screen_t"] = round(o["death_t"], 2)
    return {"id": f"shot-{n:02d}", "kind": kind, "moment": o["moment"], "reason": o["reason"],
            "video_t": round(o["video_t"], 2), "replay_tick": o["replay_tick"], "ticks": o["ticks"],
            "dur_s": o["dur_s"], "params": params, "status": "planned", "file": None, "qa": None,
            "source": o["src"]}


def plan_table(plan: dict) -> str:
    rows = [f"{'#':<8}{'video_t':>8}  {'kind':<17}{'moment':<10}{'dur':>5}{'tick':>7}  reason"]
    for s in plan["shots"]:
        m, sec = divmod(s["video_t"], 60)
        rows.append(f"{s['id']:<8}{int(m):d}:{sec:05.2f}  {s['kind']:<17}{s['moment']:<10}{s['dur_s']:>5.1f}"
                    f"{str(s['replay_tick'] if s['replay_tick'] is not None else '-'):>7}  {s['reason']}")
    sy = plan["sync"]
    rows.append(f"sync: offset {sy['offset_s']:+.2f}s via {sy['method']} (confidence {sy['confidence']})")
    for k in plan.get("skipped", []):
        rows.append(f"  skipped {k['kind']:<16} {k['why']}  [{k['reason']}]")
    return "\n".join(rows)


# =============================================================================================== jobs + exporters
def _try_keyframes(shot: dict, replay):
    """Flashback editor-state keyframes from flashback_keyframes when that module can build this shot kind."""
    try:
        from . import flashback_keyframes as FK
    except Exception:                                                # noqa: BLE001 - optional module
        return None
    fn = getattr(FK, "build_shot", None)
    if fn is None or replay is None or shot["replay_tick"] is None:
        return None
    try:
        return fn(shot["kind"], replay, shot["replay_tick"], shot["ticks"])
    except Exception as e:                                           # noqa: BLE001
        print(f"[cinematic] flashback_keyframes could not build {shot['id']}: {type(e).__name__}: {e}", file=sys.stderr)
        return None


def job_dir(slug: str) -> Path:
    return JOBS_DIR / slug


def queue_jobs(slug: str, plan: dict | None = None, replay=None, retry_rejected: bool = False) -> list[Path]:
    """Write studio/cinematic_jobs/<slug>/job-XX.json for every shot still to render; marks them `queued`."""
    plan = plan or load_shots(slug)
    if not plan:
        raise SystemExit(f"{slug}: no shots.json - run: mcs cinematic plan {slug}")
    if replay is None and plan.get("replay") and plan.get("replay_kind") == "flashback" and Path(plan["replay"]).exists():
        try:
            replay = load_replay(plan["replay"])
        except Exception:                                            # noqa: BLE001
            replay = None
    jd = job_dir(slug)
    jd.mkdir(parents=True, exist_ok=True)
    out = []
    redo = {"planned", "queued", "failed"} | ({"rejected"} if retry_rejected else set())
    for i, s in enumerate(plan["shots"], 1):
        if s["status"] not in redo:
            continue
        vis = s["params"]["visuals"]
        job = {"version": 1, "job_id": f"job-{i:02d}", "project": slug, "shot_id": s["id"], "kind": s["kind"],
               "replay": {"path": plan.get("replay"), "kind": plan.get("replay_kind")},
               "tick_start": s["replay_tick"], "ticks": s["ticks"],
               "tick_end": None if s["replay_tick"] is None else s["replay_tick"] + (
                   s["params"].get("replay_ticks_covered") or s["ticks"]),
               "dur_s": s["dur_s"], "anchor": s["params"].get("anchor"),
               "camera": {"abstract": s["params"]["camera"], "keyframes": _try_keyframes(s, replay)},
               "visuals": {"hide_gui": vis["hide_gui"], "hide_nametags": vis["hide_nametags"],
                           "hide_chat": vis["hide_chat"], "night_vision": vis["night_vision"],
                           "time_of_day_override": vis["time_of_day"]},
               "export": {"width": 1920, "height": 1080, "fps": s["params"]["fps"], "codec": "h264",
                          "output": f"broll/{s['id']}.mp4",
                          "output_abs": str((PROJECTS / slug / "broll" / f"{s['id']}.mp4").resolve())},
               "status": "queued"}
        p = jd / f"{job['job_id']}.json"
        _write(p, job)
        s["status"], s["job"] = "queued", p.name
        out.append(p)
    _write(shots_path(slug), plan)
    return out


