def ffprobe_video(path: Path) -> dict:
    r = subprocess.run(["ffprobe", "-v", "error", "-show_entries",
                        "stream=codec_type,width,height,avg_frame_rate,duration:format=duration", "-of", "json",
                        str(path)], capture_output=True, text=True, timeout=60)
    j = json.loads(r.stdout or "{}")
    v = next((s for s in j.get("streams", []) if s.get("codec_type") == "video"), {})
    num, _, den = (v.get("avg_frame_rate") or "0/1").partition("/")
    den_f = float(den or 1)
    return {"w": int(v.get("width", 0)), "h": int(v.get("height", 0)),
            "fps": float(num) / den_f if den_f else 0.0,
            "dur": float(v.get("duration") or j.get("format", {}).get("duration") or 0),
            "has_audio": any(s.get("codec_type") == "audio" for s in j.get("streams", []))}


def sample_frames(path: Path, n: int = 8, w: int = 320, h: int = 180, dur: float | None = None) -> np.ndarray:
    """n evenly spaced RGB frames -> uint8 (n, h, w, 3)."""
    dur = dur or ffprobe_video(path)["dur"] or 1.0
    r = subprocess.run(["ffmpeg", "-v", "error", "-threads", "2", "-i", str(path), "-an", "-vf",
                        f"fps={n / max(dur, 0.1):.4f},scale={w}:{h}:flags=area,format=rgb24", "-frames:v", str(n),
                        "-f", "rawvideo", "-"], capture_output=True, timeout=300)
    buf = np.frombuffer(r.stdout, dtype=np.uint8)
    k = len(buf) // (w * h * 3)
    return buf[: k * w * h * 3].reshape(k, h, w, 3)


def project_ref_luma(slug: str | None) -> float | None:
    """Typical luma (0-255) of the creator's own footage (cached): night/cave sessions are naturally dark."""
    if not slug:
        return None
    cache = PROJECTS / slug / "work" / "cinematic_luma.json"
    c = _read(cache)
    if c:
        return c.get("luma")
    try:
        f = ((_read(PROJECTS / slug / "project.json", {}) or {}).get("sources") or {}).get("game", {}).get("file")
        if not f or not Path(f).exists():
            return None
        d = _probe_duration(Path(f)) or 0
        vals = []
        for k in range(1, 7):
            r = subprocess.run(["ffmpeg", "-v", "error", "-ss", f"{d * k / 7:.2f}", "-i", f, "-frames:v", "1", "-vf",
                                "scale=64:36,format=gray", "-f", "rawvideo", "-"], capture_output=True, timeout=60)
            if r.stdout:
                vals.append(float(np.frombuffer(r.stdout, np.uint8).mean()))
        if vals:
            luma = round(float(np.median(vals)), 1)
            _write(cache, {"luma": luma})
            return luma
    except Exception:                                                # noqa: BLE001
        pass
    return None


def qa_clip(path: str | Path, expect: dict | None = None, ref_luma: float | None = None) -> dict:
    """Sample frames and reject unusable B-roll. expect = {w,h,fps,dur}. Returns
    {ok, reasons[], notes[], metrics{}}; a rejected clip stays on disk, the caller records the reason."""
    path = Path(path)
    res = {"ok": True, "reasons": [], "notes": [], "metrics": {}}
    if not path.exists() or path.stat().st_size == 0:
        return {**res, "ok": False, "reasons": ["missing or empty file"]}
    try:
        info = ffprobe_video(path)
        fr = sample_frames(path, 8, dur=info["dur"])
    except Exception as e:                                           # noqa: BLE001
        return {**res, "ok": False, "reasons": [f"unreadable video ({type(e).__name__})"]}
    if len(fr) < 3 or info["w"] == 0:
        return {**res, "ok": False, "reasons": ["no decodable frames"]}
    m = res["metrics"]
    gray = fr.astype(np.float32) @ np.array([0.299, 0.587, 0.114], dtype=np.float32)
    luma = gray.mean(axis=(1, 2))
    m["luma_mean"] = round(float(luma.mean()), 1)
    m["probe"] = {k: (round(v, 2) if isinstance(v, float) else v) for k, v in info.items()}
    # --- too dark (night footage is naturally dark, so compare to the creator's own footage)
    dark_thr = 25.0 if (ref_luma is None or ref_luma >= 70) else max(10.0, ref_luma * 0.35)
    dark = m["luma_mean"] < dark_thr or float((luma < dark_thr).mean()) >= 0.6
    if dark:
        res["reasons"].append(f"mostly black / very dark (mean luma {m['luma_mean']}, threshold {dark_thr:.0f})")
        res["notes"].append("remedy: re-export with night vision on, or a time-of-day override (golden hour / day), "
                            "or lift it in the edit with the `brighten` effect")
    # --- frozen / static
    diffs = np.abs(np.diff(gray, axis=0)).mean(axis=(1, 2))
    m["motion"] = round(float(diffs.mean()), 2)
    if m["motion"] < 0.8:
        res["reasons"].append(f"frozen / static (frame-to-frame change {m['motion']})")
    # --- extreme blur: mean |laplacian| of the sharper half of the frames
    lap = np.abs(4 * gray[:, 1:-1, 1:-1] - gray[:, :-2, 1:-1] - gray[:, 2:, 1:-1] - gray[:, 1:-1, :-2]
                 - gray[:, 1:-1, 2:])
    sharp = float(np.sort(lap.mean(axis=(1, 2)))[len(lap) // 2:].mean())
    m["sharpness"] = round(sharp, 3)
    if sharp < 0.35 and not dark:
        res["reasons"].append(f"extreme blur / no detail (sharpness {m['sharpness']})")
    # --- camera inside a block: one flat colour covers most of the frame in most samples
    q = (fr[:, ::2, ::2, :] // 24).astype(np.int32)
    keys = q[..., 0] * 100 + q[..., 1] * 10 + q[..., 2]
    big = []
    for k in keys:
        _, cnt = np.unique(k, return_counts=True)
        big.append(cnt.max() / k.size)
    m["flat_area"] = round(float(np.median(big)), 2)
    if m["flat_area"] > 0.75 and not dark:
        res["reasons"].append(f"camera probably inside a block ({m['flat_area']:.0%} of the frame is one flat colour)")
    # --- format
    if expect:
        if expect.get("w") and (info["w"], info["h"]) != (expect["w"], expect["h"]):
            res["reasons"].append(f"wrong size {info['w']}x{info['h']} (want {expect['w']}x{expect['h']})")
        if expect.get("fps") and abs(info["fps"] - expect["fps"]) > 1.0:
            res["reasons"].append(f"wrong fps {info['fps']:.1f} (want {expect['fps']})")
        if expect.get("dur") and (info["dur"] < expect["dur"] * 0.8 or info["dur"] > expect["dur"] + 0.6):
            res["reasons"].append(f"wrong duration {info['dur']:.2f}s (want {expect['dur']:.2f}s)")
    res["ok"] = not res["reasons"]
    return res


# =============================================================================================== render queue
def render_queue(slug: str, exporter: str | None = None, force: bool = False) -> dict:
    """Run the chosen exporter over queued jobs, QA each clip, update shots.json. Returns counts."""
    plan = load_shots(slug)
    if not plan:
        raise SystemExit(f"{slug}: no shots.json - run: mcs cinematic plan {slug}")
    C = cfg(SET.load(slug))
    name = exporter or C["exporter"]
    if name not in EXPORTERS:
        raise SystemExit(f"unknown exporter {name!r}; choose from {sorted(EXPORTERS)}")
    if C["render_only_when_idle"] and name != "manual" and not force and not machine_idle():
        print("[cinematic] Minecraft or OBS is running - not rendering now (settings: render_only_when_idle). "
              "Use --force to override.")
        return {"rendered": 0, "rejected": 0, "failed": 0, "waiting": 0, "deferred": True}
    exp = EXPORTERS[name]()
    ref = project_ref_luma(slug)
    counts = {"rendered": 0, "rejected": 0, "failed": 0, "waiting": 0}
    for s in plan["shots"]:
        if s["status"] not in ("queued", "failed"):
            continue
        job = _read(job_dir(slug) / (s.get("job") or "none.json"))
        if not job:
            s["status"], s["note"] = "failed", "job file missing - re-run queue"
            counts["failed"] += 1
            continue
        try:
            out = exp.render(job)
        except NotImplementedError as e:
            print(f"[cinematic] {s['id']}: {e}")
            counts["failed"] += 1
            s["status"], s["note"] = "failed", str(e)
            continue
        except Exception as e:                                       # noqa: BLE001
            counts["failed"] += 1
            s["status"], s["note"] = "failed", f"{type(e).__name__}: {e}"
            print(f"[cinematic] {s['id']} failed: {s['note']}")
            continue
        if out is None:
            counts["waiting"] += 1
            continue
        ex = job["export"]
        qa = qa_clip(out, {"w": ex["width"], "h": ex["height"], "fps": ex["fps"], "dur": job["dur_s"]}, ref)
        s["file"], s["qa"] = ex["output"], qa
        s["status"] = "rendered" if qa["ok"] else "rejected"
        s.pop("note", None)
        if not qa["ok"]:
            s["note"] = "; ".join(qa["reasons"])
        counts[s["status"]] += 1
        print(f"[cinematic] {s['id']} {s['kind']:<16} {s['status']}" + ("" if qa["ok"] else f"  ({s['note']})"))
        _write(shots_path(slug), plan)
    _write(shots_path(slug), plan)
    if name == "manual" and counts["waiting"]:
        print(f"[cinematic] checklist written: {job_dir(slug) / 'CHECKLIST.md'}")
    return counts


# =============================================================================================== splice
def _whoosh(slug: str, seed: int = 1) -> str | None:
    try:
        from . import assets as A
        res = A.find(A.Query(roles=["whoosh"], max_duration=1.6, max_energy=3, project=slug, limit=4, seed=seed))
        return res[0]["id"] if res else None
    except Exception:                                                # noqa: BLE001
        return None


def splice(edl: dict, slug: str, S: dict | None = None) -> tuple[dict, dict]:
    """Add rendered + QA-passed shots as full-frame muted `video` overlays (and a soft whoosh). Returns (edl, report).
    Idempotent: earlier cinematic overlays/sfx are removed first. No usable shots -> the edl comes back unchanged."""
    S = S if S is not None else SET.load(slug)
    C = cfg(S)
    report: dict = {"added": [], "skipped": []}
    plan = load_shots(slug)
    if not plan or not C["enabled"]:
        report["note"] = "cinematic disabled" if plan else "no shots.json"
        return edl, report
    out = copy.deepcopy(edl)
    out["overlays"] = [o for o in out.get("overlays", []) if not o.get("cinematic")]
    out.setdefault("audio", {}).setdefault("sfx", [])
    out["audio"]["sfx"] = [e for e in out["audio"]["sfx"] if not e.get("cinematic")]
    usable = [s for s in plan["shots"] if s["status"] == "rendered" and (s.get("qa") or {}).get("ok", True)
              and s["kind"] in C["allowed_kinds"] and s.get("file")]
    if not usable:
        report["note"] = "no rendered shots"
        return out, report
    from . import assets as A
    from .edl import build_spans, validate

    def look(i):
        try:
            return A.get(i)
        except Exception:                                            # noqa: BLE001
            return None
    spans = build_spans(out, look)
    busy = busy_output_intervals(out, spans, pad=0.3)
    sfx_on = S.get("audio", {}).get("sfx", True) and SET.role_ok(S, ["whoosh"]) and C["whoosh"]
    who = _whoosh(slug) if sfx_on else None
    placed: list[tuple[float, float]] = []
    new_ov, new_sfx = [], []
    for sh in sorted(usable, key=lambda s: s["video_t"]):
        if not (PROJECTS / slug / sh["file"]).exists():
            report["skipped"].append({"id": sh["id"], "why": "clip file missing"})
            continue
        dur = sh["dur_s"]
        cover = [sp for sp in spans if sp.src_in is not None and not str(sp.seg_id or "").startswith("cold")
                 and (sp.speed == 1.0 or sh["kind"] == "timelapse")
                 and sp.src_in - 0.01 <= sh["video_t"] < sp.src_in + (sp.out_end - sp.out_start) * sp.speed]
        if not cover:
            report["skipped"].append({"id": sh["id"], "why": "that footage was cut from the edit"})
            continue
        sp = cover[0]
        src_end = sp.src_in + (sp.out_end - sp.out_start) * sp.speed
        src_at = sh["video_t"]
        if src_at + dur * sp.speed > src_end + 1e-6:                  # slide earlier so the clip ends with the segment
            src_at = src_end - dur * sp.speed - 0.02
            if src_at < sp.src_in:
                report["skipped"].append({"id": sh["id"], "why": "segment shorter than the shot"})
                continue
        o0 = sp.out_start + (src_at - sp.src_in) / sp.speed
        o1 = o0 + dur
        if o0 < C["hook_s"]:
            report["skipped"].append({"id": sh["id"], "why": f"inside the hook (first {C['hook_s']:g}s)"})
            continue
        clash = next((w for a, z, w in busy if o0 < z and o1 > a), None)
        if clash:
            report["skipped"].append({"id": sh["id"], "why": f"overlaps {clash}"})
            continue
        if any(not (o0 >= b1 + C["min_gap_s"] or o1 + C["min_gap_s"] <= b0) for b0, b1 in placed):
            report["skipped"].append({"id": sh["id"], "why": "too close to another shot"})
            continue
        placed.append((o0, o1))
        new_ov.append({"type": "video", "file": sh["file"], "placement": "fullscreen", "audio": False,
                       "seg": sp.seg_id, "src_at": round(src_at, 3), "dur": dur, "cinematic": sh["id"],
                       "kind": sh["kind"]})
        if who:
            new_sfx.append({"asset": who, "seg": sp.seg_id, "src_at": round(src_at + 0.05, 3), "align": "peak",
                            "volume_db": -2, "cinematic": sh["id"]})
        report["added"].append({"id": sh["id"], "kind": sh["kind"], "out_at": round(o0, 2), "seg": sp.seg_id})
    out["overlays"] = new_ov + out["overlays"]          # underneath stickers / motion graphics / avatar, above the footage
    out["audio"]["sfx"] = out["audio"]["sfx"] + new_sfx
    validate(out)
    if not report["added"]:
        return edl, report
    return out, report


def splice_into_edl(edl: dict, slug: str) -> dict:
    """Pure function used by autopilot: the edl with cinematic B-roll overlays added (unchanged if there is none)."""
    try:
        return splice(edl, slug)[0]
    except Exception as e:                                           # noqa: BLE001 - B-roll must never break an edit
        print(f"[cinematic] splice skipped: {type(e).__name__}: {e}", file=sys.stderr)
        return edl


# =============================================================================================== CLI
def status_text(slug: str) -> str:
    p = load_shots(slug)
    if not p:
        return f"{slug}: no shots.json yet (mcs cinematic plan {slug})"
    sy = p["sync"]
    lines = [f"{slug}: replay {p.get('replay') or '-'} ({p.get('replay_kind')})",
             f"  sync {sy['offset_s']:+.2f}s via {sy['method']} conf {sy['confidence']} - {sy['notes']}"]
    c: dict = {}
    for s in p["shots"]:
        lines.append(f"  {s['id']} {s['video_t']:>7.2f}s {s['kind']:<16} {s['status']:<9} {s.get('file') or '-'}"
                     + (f"  [{s['note']}]" if s.get("note") else ""))
        c[s["status"]] = c.get(s["status"], 0) + 1
    lines.append("  totals: " + (", ".join(f"{v} {k}" for k, v in sorted(c.items())) or "no shots"))
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> None:
    ap = argparse.ArgumentParser(prog="mcs cinematic", description="Replay-powered cinematic B-roll director")
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("plan", help="choose shots and write projects/<slug>/broll/shots.json (+ queue jobs)")
    p.add_argument("slug")
    p.add_argument("--replay", help="replay zip (default: auto-find by timestamps)")
    p.add_argument("--synthetic", action="store_true", help="use a synthetic replay (dry run / tests)")
    p.add_argument("--offset", type=float, help="force sync offset seconds (replay time at video t=0)")
    p.add_argument("--no-queue", action="store_true")
    p = sub.add_parser("render", help="run the exporter on queued jobs and QA each clip")
    p.add_argument("slug")
    p.add_argument("--exporter", choices=sorted(EXPORTERS))
    p.add_argument("--force", action="store_true", help="render even if Minecraft/OBS is running")
    p.add_argument("--retry-rejected", action="store_true")
    p = sub.add_parser("status")
    p.add_argument("slug")
    p = sub.add_parser("splice", help="write edit.json with cinematic overlays (backup: edit.v_precinematic.json)")
    p.add_argument("slug")
    p = sub.add_parser("qa", help="QA one clip")
    p.add_argument("file")
    p.add_argument("--project", help="compare darkness with this project's footage")
    p = sub.add_parser("sync", help="show replay candidates and the sync estimate for a project")
    p.add_argument("slug")
    sub.add_parser("selftest", help="run tests/test_cinematic.py")
    a = ap.parse_args(argv)

    if a.cmd == "plan":
        rep = a.replay
        if a.synthetic:
            rep = synthetic_replay(float((_read(PROJECTS / a.slug / "project.json", {}) or {}).get("duration_s", 120)) + 60)
        sync = {"offset_s": a.offset, "method": "event", "confidence": 1.0, "notes": "forced on the command line"} \
            if a.offset is not None else None
        if a.synthetic and sync is None:
            sync = {"offset_s": 10.0, "method": "timestamps", "confidence": 0.5, "notes": "synthetic replay"}
        plan = plan_shots(a.slug, rep, sync=sync)
        print(plan_table(plan))
        for n in plan.get("notes", []):
            print("note:", n)
        if not a.no_queue and plan["shots"]:
            jobs = queue_jobs(a.slug, plan, replay=rep if a.synthetic else None)
            print(f"[cinematic] queued {len(jobs)} job(s) in {job_dir(a.slug)}")
    elif a.cmd == "render":
        if a.retry_rejected:
            queue_jobs(a.slug, retry_rejected=True)
        print(render_queue(a.slug, a.exporter, a.force))
    elif a.cmd == "status":
        print(status_text(a.slug))
    elif a.cmd == "splice":
        d = PROJECTS / a.slug
        edl = json.loads((d / "edit.json").read_text(encoding="utf-8"))
        new, rep = splice(edl, a.slug)
        if not rep["added"]:
            print("[cinematic] nothing to splice:", rep.get("note") or rep["skipped"])
            return
        bak = d / "edit.v_precinematic.json"
        if not bak.exists():
            shutil.copyfile(d / "edit.json", bak)
        (d / "edit.json").write_text(json.dumps(new, indent=2), encoding="utf-8")
        print(f"[cinematic] spliced {len(rep['added'])} shot(s): "
              + ", ".join(f"{x['id']}@{x['out_at']}s" for x in rep["added"]))
        for s in rep["skipped"]:
            print(f"  skipped {s['id']}: {s['why']}")
    elif a.cmd == "qa":
        res = qa_clip(a.file, ref_luma=project_ref_luma(a.project))
        print(json.dumps(res, indent=2))
        sys.exit(0 if res["ok"] else 1)
    elif a.cmd == "sync":
        vw = video_window(a.slug)
        print(f"video: {datetime.fromtimestamp(vw['start']):%Y-%m-%d %H:%M:%S} .. "
              f"{datetime.fromtimestamp(vw['end']):%H:%M:%S} ({vw['how']})")
        for r in list_replays():
            print(f"replay {r['kind']:<9} {Path(r['path']).name:<28} {datetime.fromtimestamp(r['start']):%H:%M:%S}.."
                  f"{datetime.fromtimestamp(r['end']):%H:%M:%S} overlap {overlap_s(vw, r):.0f}s")
        f = find_replay(a.slug, window=vw)
        print("chosen:", f["path"] if f else "none")
        if f:
            print(estimate_sync(vw, f))
    elif a.cmd == "selftest":
        import runpy
        runpy.run_path(str(STUDIO / "tests" / "test_cinematic.py"), run_name="__main__")


if __name__ == "__main__":
    main()

