p = r"C:\Users\edmem\OneDrive\Desktop\Minecraft Channel\studio\mcstudio\cinematic.py"
s = open(p, encoding="utf-8").read()
a = s.index("def _try_keyframes(")
b = s.index("def job_dir(")
new = '''def _fk_shot(FK, kind: str, replay, tick: int, ticks: int, cam: dict):
    """Build a flashback_keyframes.Shot (one editor scene) for a cinematic shot kind."""
    track = replay.player_track()
    uuid = getattr(track, "key", None) or getattr(replay, "local_uuid", None) or "00000000-0000-0000-0000-000000000000"
    tg = FK.Target(track.pos, track.rot, uuid, "player")
    secs = ticks / 20.0
    name = f"{kind}@{tick}"
    if kind in ("orbit",):
        return FK.orbit(tg, tick, secs, radius=cam.get("radius", 5.5), height=cam.get("height", 2.2),
                        revolutions=cam.get("sweep_deg", 120) / 360.0, name=name)
    if kind == "push_in":
        return FK.push_in(tg, tick, secs, start_dist=cam.get("from_dist", 9) + 3, end_dist=cam.get("to_dist", 2.8), name=name)
    if kind in ("drone_pullup", "death_reveal", "outro_pullup"):
        return FK.drone_pullup(tg, tick, secs, start_dist=cam.get("from_height", 2) + 1.5,
                               end_dist=cam.get("to_height", 35) * (1.0 if kind != "death_reveal" else 1.6),
                               end_pitch=abs(cam.get("pitch_end", -60)), name=name)
    if kind == "flyby":
        return FK.flyby(tg, tick, secs, side=cam.get("lateral", 8), height=cam.get("height", 4), name=name)
    if kind in ("track_follow", "spectate"):
        return FK.track_follow(tg, tick, secs, distance=cam.get("behind", 3.2) + 1.0, up=cam.get("height", 1.9) - 1.0,
                               uuid=uuid, name=name)
    if kind == "pov":                      # first person: Flashback's own entity tracking with the camera AT the head
        return FK.track_follow(tg, tick, secs, distance=0.0, up=0.0, part="HEAD", pitch_offset=0.0, uuid=uuid, name=name)
    if kind == "timelapse":
        return FK.timelapse(tg, tick, tick + int(ticks * cam.get("time_scale", 8)), video_seconds=secs, name=name)
    if kind in ("aerial_establish", "nether_arrival"):      # descending aerial: orbit-style, shrinking distance, tilting up
        ticks_l = sorted({tick + round(i * ticks / 6) for i in range(7)})
        kfs = {}
        yaw0 = tg.rot(tick)[0]
        for i, t in enumerate(ticks_l):
            u = i / max(1, len(ticks_l) - 1)
            x, y, z = tg.pos(t)
            dist = cam.get("distance", 28) * (1 - 0.55 * u) + 8
            kfs[t] = FK.orbit_kf((x, y + 1.0, z), dist, yaw0 + 25 * u, 62 - 30 * u)
        return FK.Shot(name, kind, tick, ticks_l[-1], [FK.Track("CAMERA_ORBIT", kfs)], "descending aerial", {})
    return None


def _try_keyframes(shot: dict, replay):
    """Flashback editor-state for this shot via flashback_keyframes (one scene, visual overrides applied):
    {"template", "editor_state", "errors"} or None when no replay / module / template."""
    if replay is None or shot["replay_tick"] is None or not hasattr(replay, "player_track"):
        return None
    try:
        from . import flashback_keyframes as FK
        vis = shot["params"]["visuals"]
        sh = _fk_shot(FK, shot["kind"], replay, int(shot["replay_tick"]), int(shot["ticks"]), shot["params"]["camera"])
        if sh is None:
            return None
        state = FK.build_state([sh], FK.Visuals(hide_nametags=vis["hide_nametags"], hide_hud=vis["hide_gui"],
                                                night_vision=vis["night_vision"], time_of_day=vis["time_of_day"]),
                               getattr(replay, "path", None))
        return {"template": sh.kind, "export_range_ticks": [sh.start, sh.end], "editor_state": state,
                "errors": FK.validate_state(state)}
    except Exception as e:                                           # noqa: BLE001 - optional module
        print(f"[cinematic] flashback_keyframes could not build {shot['id']}: {type(e).__name__}: {e}", file=sys.stderr)
        return None


'''
s = s[:a] + new + s[b:]
open(p, "w", encoding="utf-8").write(s)
print("ok")

